// mystery-v3.1 server rules facade. Pure module (no Deno APIs); unit-tested under Node/Vitest.
// Everything game-specific comes from the shared copies of the browser modules (supabase/functions/_shared/mystery,
// generated by `npm run sync:shared`): the offer from draft.ts, the egg tier from scoring.ts, the verdict from
// caseLogic.ts, ids/clues/suspects from the data registries. Nothing here re-implements game math.
import { MYSTERY_DATA, MYSTERY_EGG, type MysteryData, type MysteryEggRules } from './mystery-registry.generated.ts';
import { draftOffer } from './mystery/draft.ts';
import { eggTierForSeed, round1, scoreFor } from './mystery/scoring.ts';
import { isCorrectSuspect, verdictFor } from './mystery/caseLogic.ts';
import { NIGHTSHADE_IDS, MYSTERY_RULES_VERSION } from './mystery/types.ts';
import type { CaseDef, ClueId, DnfReason, DuoOffer, MysteryRulesVersion, SuspectId, Verdict } from './mystery/types.ts';
import { isPokemonId } from './game/index.ts';
import { HttpError } from './errors.ts';
import type { LiveEggTier, MysteryProgress, RulesContext } from './mystery-events.ts';

export { MYSTERY_RULES_VERSION };

export function requireData(data: MysteryData | null = MYSTERY_DATA): MysteryData {
  if (!data) {
    throw new HttpError('MISCONFIGURED', 'Mystery data registries are not deployed (run npm run sync:shared, then redeploy)');
  }
  return data;
}

export function requireEggRules(egg: MysteryEggRules | null = MYSTERY_EGG): MysteryEggRules {
  if (!egg) throw new HttpError('MISCONFIGURED', 'Mystery egg tuning is not deployed (run npm run sync:shared, then redeploy)');
  return egg;
}

// ------------------------------------------------------------------------------------------------- offer
const ROLES = ['investigation', 'stealth', 'mobility', 'control', 'defense', 'support'];
const RARITIES = ['common', 'rare', 'epic'];
const STAT_KEYS = ['investigation', 'stealth', 'mobility', 'defense', 'hydeControl', 'eggProtection'] as const;
const MAX_CARD_BYTES = 8192;

/**
 * Defence in depth before anything is stored: exactly three well-formed cards for THIS seed, valid ids, no duplicate
 * pair, six stats in 1..5. A failure means the shared draft module is broken -> 500, never a stored bad offer.
 */
export function assertValidOffer(offer: DuoOffer, seed: string): void {
  const fail = (why: string): never => {
    throw new HttpError('INTERNAL', 'Offer generation failed a server sanity check', { reason: why });
  };
  if (!offer || offer.seed !== seed) fail('seed mismatch');
  if (!Array.isArray(offer.cards) || offer.cards.length !== 3) fail('not exactly three cards');
  const pairs = new Set<string>();
  for (const card of offer.cards) {
    if (!NIGHTSHADE_IDS.includes(card.characterId)) fail('unknown character');
    if (!isPokemonId(card.pokemonId)) fail('unknown pokemon');
    const key = `${card.characterId}:${card.pokemonId}`;
    if (pairs.has(key)) fail('duplicate pair');
    pairs.add(key);
    if (typeof card.duoName !== 'string' || card.duoName.length < 1 || card.duoName.length > 60) fail('duo name');
    if (!ROLES.includes(card.role)) fail('role');
    if (!RARITIES.includes(card.rarity)) fail('rarity');
    for (const k of STAT_KEYS) {
      const v = card.stats?.[k];
      if (typeof v !== 'number' || !Number.isFinite(v) || v < 1 || v > 5) fail(`stat ${k}`);
    }
    if (JSON.stringify(card).length > MAX_CARD_BYTES) fail('card too large');
  }
}

/** The three cards for a seed: the SAME pure draftOffer(seed) the browser runs, so the client cannot forge cards. */
export function computeOffer(seed: string): DuoOffer {
  requireData();
  const offer = draftOffer(seed);
  assertValidOffer(offer, seed);
  return offer;
}

// ------------------------------------------------------------------------------------------------- rules context
export function expectedEggTier(seed: string, egg: MysteryEggRules = requireEggRules()): LiveEggTier {
  return eggTierForSeed(seed, egg.tierWeights);
}

export function rulesContext(seed: string, caseDef: CaseDef, egg: MysteryEggRules): RulesContext {
  return {
    clueIds: caseDef.clues.map((c) => c.id),
    suspectIds: caseDef.suspects.map((s) => s.id),
    eggPoints: { ...egg.points },
    expectedTier: expectedEggTier(seed, egg),
  };
}

// ------------------------------------------------------------------------------------------------- result
/** What the client CLAIMED (finish event + optional RunResult in the finalize body). Stored for audit only. */
export interface ClientClaim {
  finishVerdict?: Verdict;
  finishScore?: number;
  accusationCorrect?: boolean;
  result?: Record<string, unknown>;
}

/** Server-recomputed result, camelCase, as passed to mystery_finalize_session (and returned to clients). */
export interface ServerResult {
  rulesVersion: MysteryRulesVersion;
  outcome: 'finished' | 'dnf';
  dnfReason: DnfReason | null;
  verdict: Verdict;
  accused: SuspectId | null;
  correct: boolean;
  cluesFound: ClueId[];
  eggTier: LiveEggTier | null;
  eggPoints: number;
  eggSecurity: number;
  activeTimeS: number;
  score: number | null;
  catches: number;
  sightings: number;
  hintsUsed: number;
  clientClaim: ClientClaim;
  claimMatches: boolean;
}

const near = (a: unknown, b: number | null) => (b === null ? a === null || a === undefined : typeof a === 'number' && Math.abs(a - b) < 0.05);

/**
 * Recomputes the result from validated progress with the shared scoring + case logic.
 *   finished: activeTimeS = round1(t of egg_delivered) (the clock stops at the deposit), score = scoreFor(points, t)
 *             = round1(points × 100 − activeTimeS); verdict = verdictFor(case, clues, accused) (null → not_accused)
 *   dnf:      score null, verdict not_accused, eggPoints 0, activeTimeS = round1(t of the dnf event)
 */
export function computeResult(
  progress: MysteryProgress,
  caseDef: CaseDef,
  expectedTier: LiveEggTier | null,
  clientResult?: Record<string, unknown>,
): ServerResult {
  const term = progress.terminal;
  if (!term) throw new HttpError('RUN_NOT_FINISHED', 'No finish or dnf event has been recorded yet', { lastSeq: progress.lastSeq });
  const security = Math.max(0, Math.min(100, round1(progress.eggSecurity)));
  const base = {
    rulesVersion: MYSTERY_RULES_VERSION,
    cluesFound: [...progress.cluesFound],
    catches: progress.catches,
    sightings: progress.sightings,
    hintsUsed: progress.hints,
  };

  if (term.type === 'finish') {
    const d = progress.delivered;
    const acc = progress.accusation;
    if (!d || !acc) throw new HttpError('INVALID_TRANSITION', 'finish without delivery/accusation passed validation');
    const accused = acc.suspectId;
    const verdict = verdictFor(caseDef, progress.cluesFound, accused);
    const correct = isCorrectSuspect(caseDef, accused);
    const activeTimeS = round1(d.t);
    const score = scoreFor(d.points, d.t);
    const claim: ClientClaim = { finishVerdict: term.claimedVerdict, finishScore: term.claimedScore, accusationCorrect: acc.claimedCorrect };
    if (clientResult) claim.result = clientResult;
    const claimMatches = term.claimedVerdict === verdict && near(term.claimedScore, score) && acc.claimedCorrect === correct
      && (!clientResult || (
        clientResult.outcome === 'finished' && clientResult.verdict === verdict && near(clientResult.score, score)
        && near(clientResult.activeTimeS, activeTimeS)
      ));
    return {
      ...base, outcome: 'finished', dnfReason: null, verdict, accused, correct, eggTier: d.tier, eggPoints: d.points,
      eggSecurity: Math.max(0, Math.min(100, round1(d.security))), activeTimeS, score, clientClaim: claim, claimMatches,
    };
  }

  const claim: ClientClaim = {};
  if (clientResult) claim.result = clientResult;
  return {
    ...base, outcome: 'dnf', dnfReason: term.reason, verdict: 'not_accused', accused: null, correct: false,
    eggTier: expectedTier, eggPoints: 0, eggSecurity: security, activeTimeS: round1(term.t), score: null,
    clientClaim: claim,
    claimMatches: !clientResult || (clientResult.outcome === 'dnf' && (clientResult.score === null || clientResult.score === undefined)),
  };
}
